<?php
require_once __DIR__.'/app/lib/Db.php';
require_once __DIR__.'/app/lib/RegionalCategorySeo.php';
require_once __DIR__.'/app/lib/SeoTopicCluster.php';
$config=require __DIR__.'/app/config.php';$pdo=Db::pdo();
$path=parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'/';
if(!preg_match('#^/regional/([a-z0-9-]+)/([a-z0-9-]+)/?$#',$path,$m)){http_response_code(404);exit('Not found');}
$page=RegionalCategorySeo::page($pdo,$m[1],$m[2]);if(!$page){http_response_code(404);exit('Not found');}
$c=$page['category'];$country=$page['country'];$products=$page['products'];$base=rtrim((string)$config['site_url'],'/');$canonical=$base.$page['path'];
$clusterLinks=array_values(array_filter(SeoTopicCluster::categoryLinks($pdo,(string)$c['slug']),fn($x)=>$x['path']!==$page['path']));
function re_h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$title='Verified '.$c['name'].' Availability in '.$country['name'].' | TechSelectAI';
$desc='Review '.$c['name'].' products with fresh, source-linked availability evidence for '.$country['name'].'. Unknown regional availability is excluded rather than assumed.';
$items=[];foreach($products as $i=>$p)$items[]=['@type'=>'ListItem','position'=>$i+1,'url'=>$base.'/software/'.$p['slug'],'name'=>$p['name']];
$schema=['@context'=>'https://schema.org','@graph'=>[
 ['@type'=>'Organization','@id'=>$base.'/#organization','name'=>'TechSelectAI','url'=>$base.'/'],
 ['@type'=>'WebSite','@id'=>$base.'/#website','url'=>$base.'/','name'=>'TechSelectAI','publisher'=>['@id'=>$base.'/#organization']],
 ['@type'=>'WebPage','@id'=>$canonical.'#webpage','url'=>$canonical,'name'=>$title,'description'=>$desc,'isPartOf'=>['@id'=>$base.'/#website']],
 ['@type'=>'ItemList','name'=>$c['name'].' availability in '.$country['name'],'itemListElement'=>$items],
]];
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=re_h($title)?></title><meta name="description" content="<?=re_h($desc)?>"><link rel="canonical" href="<?=re_h($canonical)?>"><meta name="robots" content="index,follow,max-snippet:-1,max-image-preview:large,max-video-preview:-1"><meta name="googlebot" content="index,follow,max-snippet:-1,max-image-preview:large,max-video-preview:-1"><meta name="bingbot" content="index,follow,max-snippet:-1,max-image-preview:large,max-video-preview:-1"><meta property="og:type" content="website"><meta property="og:site_name" content="TechSelectAI"><meta property="og:title" content="<?=re_h($title)?>"><meta property="og:description" content="<?=re_h($desc)?>"><meta property="og:url" content="<?=re_h($canonical)?>"><meta name="twitter:card" content="summary"><meta name="twitter:title" content="<?=re_h($title)?>"><meta name="twitter:description" content="<?=re_h($desc)?>"><script type="application/ld+json"><?=json_encode($schema,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)?></script><style>body{font-family:Inter,system-ui,sans-serif;margin:0;color:#172033}a{color:#145ea8}.wrap{max-width:1120px;margin:auto;padding:30px 24px}.crumbs{font-size:13px;color:#64748b}.hero{padding:34px 0 20px}.hero h1{font-size:clamp(36px,5vw,58px);margin:7px 0 12px}.lead{font-size:18px;line-height:1.65;color:#536174;max-width:920px}.notice{padding:16px;border:1px solid #dbe8ef;background:#f8fbfd;border-radius:12px;color:#536174;line-height:1.6}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px;margin-top:22px}.card{border:1px solid #e2e8f0;border-radius:14px;padding:18px}.card h2{font-size:19px;margin:5px 0 8px}.meta{font-size:13px;color:#64748b}.status{display:inline-block;padding:4px 8px;border-radius:999px;background:#eef6f7;color:#245d63;font-size:12px;font-weight:750}.source{margin-top:11px;font-size:13px}.btn{display:inline-block;margin-top:12px;padding:9px 12px;border-radius:9px;background:#123b67;color:#fff;text-decoration:none;font-weight:700}.cluster{margin-top:32px;padding:20px;border:1px solid #dbe8ef;border-radius:14px;background:#fbfdfe}.cluster h2{margin:0 0 8px}.cluster-links{display:flex;gap:10px;flex-wrap:wrap}.cluster-links a{padding:9px 12px;border:1px solid #cbd5e1;border-radius:999px;text-decoration:none;background:#fff}.cta{margin-top:36px;padding:22px;border:1px solid #d5e5ed;background:#f5f8fc;border-radius:14px}</style></head><body><main class="wrap"><div class="crumbs"><a href="/">Home</a> / <a href="/categories/<?=re_h($c['slug'])?>"><?=re_h($c['name'])?></a> / <?=re_h($country['name'])?></div><section class="hero"><div class="meta">Country-level product availability evidence</div><h1><?=re_h($c['name'])?> availability in <?=re_h($country['name'])?></h1><p class="lead"><?=re_h($desc)?></p></section><div class="notice"><strong>Evidence boundary:</strong> this page only includes products whose country availability is recorded as available or limited availability, has a source URL, confidence of at least 60%, and was verified within the last 365 days. It does not imply local compliance, data residency, Arabic support, local pricing, implementation-partner coverage, or buyer-specific fit unless those are separately verified.</div><section class="grid"><?php foreach($products as $p):?><article class="card"><div class="meta"><?=re_h($p['vendor']?:'Vendor not recorded')?> · <?=intval($p['known_capability_count'])?> known capability facts</div><h2><a href="/software/<?=re_h($p['slug'])?>"><?=re_h($p['name'])?></a></h2><span class="status"><?=re_h($p['availability_status']==='available'?'Available':'Limited availability')?></span><p><?=re_h($p['availability_notes']?:'No additional regional note recorded.')?></p><div class="meta">Regional confidence <?=round(((float)$p['regional_confidence'])*100)?>% · verified <?=re_h(date('M j, Y',strtotime((string)$p['regional_last_verified_at'])))?></div><div class="source"><a href="<?=re_h($p['source_url'])?>" rel="nofollow noopener" target="_blank">Regional evidence source ↗</a></div><a class="btn" href="/software/<?=re_h($p['slug'])?>">Review product evidence</a></article><?php endforeach;?></section><section class="cluster"><h2>Continue <?=re_h($c['name'])?> research</h2><p class="meta">Move between category, evidence-qualified buyer-intent, and other regional research without treating any page as a ranking signal.</p><div class="cluster-links"><a href="/categories/<?=re_h($c['slug'])?>">Browse the category</a><?php foreach($clusterLinks as $link):?><a href="<?=re_h($link['path'])?>"><?=re_h($link['label'])?></a><?php endforeach;?></div></section><section class="cta"><h2>Availability is only one part of the decision</h2><p>Use TechSelectAI to evaluate these products against your actual capabilities, deployment, integrations, security, compliance and commercial constraints.</p><a href="/?considering=<?=rawurlencode($c['name'])?>&country=<?=rawurlencode($country['code'])?>">Evaluate for <?=re_h($country['name'])?> →</a></section></main></body></html>
